# A mock of Design 12 F4 (the Help section), drawn in the running game with its own cells and data. Nothing here is game code.
import asyncio, sys, os
from playwright.async_api import async_playwright
from PIL import Image, ImageDraw
V = sys.argv[1]; OUT = sys.argv[2]
PREP = r"""(async () => { const W = (ms) => new Promise((r) => setTimeout(r, ms)), S = MENU.S, SH = BOOKS.shells, T = BOOKS.tech, D = FK.D; MENU.act('start'); await W(400); S.tab = null; MENU.render(true);
 Object.assign(FK.SIDES[0].store, { food: 420, wood: 380, gold: 150, stone: 90, iron: 40 }); FK.SIDES[0].age = 2; const tk = (n) => Object.keys(T).find((c) => T[c].name === n); for (const n of ['Shields', 'Spear wall', 'Fieldcraft', 'Tally sticks', 'Local guides']) { FK.SIDES[0].techs.add(tk(n)); FK.learn(0, tk(n)); }
 const h0 = FK.seatOf(0), bar = Object.keys(D.trains).find((b) => D.trains[b].join() === 'Foot'); out: for (let d = 8; d < 240; d++) for (const [i, j] of [[h0.i + d, h0.j], [h0.i - d, h0.j], [h0.i, h0.j + d], [h0.i, h0.j - d]]) { if (!ECON.canPlace(bar, i, j, 0)) continue; const t = FK.build(bar, i, j, FK.SIDES[0].col); if (t) { t.side = 0; t.done = 1; break out; } }
 const h = FK.seatOf(0); FK.select(null); S.subject = h; MENU.render(true); await W(80); window.requestAnimationFrame = () => 0; await W(80);
 const q = (s) => document.querySelector(s), V = MENU.VERBS, base = q('#base'), cell = (html, cls = '') => `<button class="cell ${cls}">${html}</button>`, pad = (L) => [...L, ...Array(Math.max(0, 6 - L.length)).fill('<i></i>')].join(''), row = (L) => `<div class="row6">${pad(L)}</div>`;
 const st = document.createElement('style'); st.textContent = `#base .hb { padding: 6px 8px; font: var(--second); line-height: 1.3; color: var(--rw); text-align: left; } #base .hb small { color: var(--wdim); font: var(--second); } #base .hb b { color: var(--g1); font-weight: 600; } #base .hb .u svg { display: inline-block; width: 10px; height: 10px; vertical-align: middle; color: var(--g1); } #base .hb i.gt { color: var(--rr); font-style: normal; } #base .hl { padding: 3px 8px 0; font: var(--second); color: var(--g1); text-align: left; } #base .hb.rule { border-top: 1px solid var(--pline); }`; document.head.appendChild(st);
 const fitAll = () => { for (const c of base.querySelectorAll('.cell')) for (const n of [...c.childNodes]) { let e = n; if (n.nodeType === 3) { if (!n.textContent.trim()) continue; e = document.createElement('span'); n.replaceWith(e); e.append(n); } else if (!n.matches('small, span:not(.bar):not(.t)')) continue; const k = (c.clientWidth - 2) / e.offsetWidth; e.style.transform = k < 1 ? `scaleX(${Math.max(0.77, k)})` : ''; } };
 const TABS = ['Tips', 'Units', 'Buildings', 'Research', 'Ages', 'Peoples'], G = MENU.guide(), sym = (k) => `<span class="u">${q('#mk-' + k) ? q('#mk-' + k).innerHTML : ''}</span>`;
 const holder = document.createElement('div'); holder.style.display = 'none'; const MK = MENU.SCR.marks; holder.innerHTML = Object.entries({ ...MK.class, Buildings: MK.bld }).map(([k, i]) => `<span id="mk-${k}">${V.train.label(Object.keys(SH).find((c) => SH[c].name === ({ Foot: 'Archer', Archers: 'Javelineer', Riders: 'Spearman', Engines: 'Swordsman', Buildings: 'Catapult' })[k]), h).match(/<svg.*?<\/svg>/)[0]}</span>`).join(''); document.body.appendChild(holder);
 window.$help = (tab, body, name) => { q('#rank .name').textContent = name || 'Help'; base.innerHTML = `<div class="row6 tabs">${TABS.map((t) => cell(t, t === tab ? 'on' : '')).join('')}</div>` + body; fitAll(); };
 const byN = (n) => Object.keys(SH).find((c) => SH[c].name === n), CL = ['Foot', 'Archers', 'Riders', 'Engines', 'Support'], units = Object.keys(SH).filter((c) => SH[c].layer === 120 && D.train[c] && !SH[c].civ), rest = units.filter((c) => !SH[c].class);
 const gt = '<i class="gt">&gt;</i>', tri = `<div class="hb">${sym('Foot')} Spearmen ${gt} ${sym('Riders')} riders ${gt} ${sym('Archers')} archers ${gt} ${sym('Foot')} spearmen. ${sym('Engines')} Engines ${gt} ${sym('Buildings')} buildings.<br><small>The symbol after a name is what that unit beats. The three numbers: health, damage a second, reach.</small></div>`;
 const A = G.units.find((u) => u.name === 'Archer');
 window.$units = () => $help('Units', tri + CL.map((cl) => row(units.filter((c) => SH[c].class === cl).map((c) => cell(V.train.label(c, h), c === byN('Archer') ? 'on' : '')))).join('') + row(rest.slice(0, 6).map((c) => cell(V.train.label(c, h)))) + `<div class="hb rule"><b>Archer</b> <small>${A.at} · ${A.age} age · ${A.secs}</small><br>Becomes: ${A.tiers.join(', ')}.<br><small>${A.why}</small></div>`);
 const blds = [...new Set(Object.keys(T).filter((c) => T[c].value.at).map((c) => T[c].value.at))], have = (b) => Object.keys(T).filter((c) => T[c].value.at === b && (!T[c].value.civ || T[c].value.civ === FK.SIDES[0].civ)), done = (b) => have(b).filter((c) => FK.SIDES[0].techs.has(c)).length;
 window.$research = () => { const C = blds.map((b) => cell(`${MENU.VERBS.pick ? (fromBook('words').brief[SH[b].name] || SH[b].name) : SH[b].name}<small>${done(b)}/${have(b).length}</small>`)), R = []; for (let i = 0; i < C.length; i += 6) R.push(row(C.slice(i, i + 6))); $help('Research', `<div class="hb"><small>Every building that researches, and how much of it you have. Tap one for its whole tree.</small></div>` + R.join('')); };
 window.$tree = (name) => { const b = byN(name), L = {}; for (const c of have(b)) (L[T[c].value.line] = L[T[c].value.line] || []).push(c); let out = ''; for (const [line, cs] of Object.entries(L)) { cs.sort((x, y) => T[x].value.age - T[y].value.age); out += `<div class="hl">${line}</div>`; for (let i = 0; i < cs.length; i += 6) out += row(cs.slice(i, i + 6).map((c) => { const ok = FK.SIDES[0].techs.has(c); return cell(ok ? `${fromBook('words').brief[T[c].name] || T[c].name}<small style="color:var(--rg)">Learned</small>` : V.research.label(c), c === Object.keys(T).find((k) => T[k].name === 'Pike square') ? 'on' : (T[c].value.age > FK.SIDES[0].age && !ok ? 'dim' : '')); })); }
   const p = G.techs.find((t) => t.name === 'Pike square'); $help('Research', out + `<div class="hb rule"><b>${p.name}</b> <small>${p.age} age · ${p.cost} · ${p.secs}${p.need ? ' · needs ' + p.need : ''} · ${p.when}</small><br>Spearmen become Pikemen: riders ×4.<br><small>${p.why || ''}</small></div>`, name); };
 return [blds.length, units.length]; })()"""
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path='/usr/bin/google-chrome', args=['--no-sandbox', '--allow-file-access-from-files'])
        pg = await b.new_page(viewport={'width': 390, 'height': 844}, device_scale_factor=2); errs = []; pg.on('pageerror', lambda e: errs.append(str(e))); await pg.goto('file://' + os.path.join(V, 'index.html') + '#20261105'); await pg.wait_for_timeout(1200)
        print(await pg.evaluate(PREP)); shots = []
        for name, js in [('1 Help · Units', '$units()'), ('2 Help · Research', '$research()'), ('3 Research · a building\'s whole tree', "$tree('Barracks')")]:
            await pg.evaluate(js); await pg.wait_for_timeout(150); f = f'/tmp/mh{len(shots)}.png'; await pg.screenshot(path=f); shots.append((name, f))
        print(errs[:3]); await b.close()
    ims = [Image.open(f) for _, f in shots]; w, h = ims[0].size; sheet = Image.new('RGB', (w * 3 + 40, h + 50), (20, 16, 12)); d = ImageDraw.Draw(sheet)
    for n, (name, _) in enumerate(shots): sheet.paste(ims[n], (n * (w + 20), 50)); d.text((n * (w + 20) + 10, 16), name, fill=(240, 230, 210), font_size=26)
    sheet.save(OUT); print(sheet.size)
asyncio.run(main())
